arr=[]
with open('graphene.dat') as f:
    for line in f:
        p=line.replace(',','.').split()
        if len(p)>=2:
            arr.append((float(p[0]),float(p[1])))
arr.sort()
xs=[x for x,y in arr]; ys=[y for x,y in arr]
w=5
sm=[]
for i in range(len(ys)):
    a=max(0,i-w//2); b=min(len(ys),i+w//2+1)
    sm.append(sum(ys[a:b])/(b-a))
for scale,name in [(0.25,'/4'),(0.1,'/10')]:
    print('\n=== scaling',name,'===')
    cand=[]
    for i in range(10,len(arr)-10):
        if sm[i]>=max(sm[i-10:i+11]):
            left=min(sm[max(0,i-100):i] or [sm[i]])
            right=min(sm[i+1:min(len(sm),i+101)] or [sm[i]])
            prom=sm[i]-max(left,right)
            if prom>10:
                cand.append((xs[i]*scale,ys[i],sm[i],prom,xs[i]))
    cand=sorted(cand,key=lambda t:t[2],reverse=True)
    keep=[]
    for c in cand:
        if all(abs(c[0]-k[0])>20 for k in keep):
            keep.append(c)
    for c in keep[:20]:
        print(f'x={c[0]:8.2f} y={c[1]:9.1f} sm={c[2]:9.1f} prom={c[3]:8.1f} raw={c[4]:9.2f}')
print('\n=== data near G candidates ===')
for lo,hi in [(6200,6500),(15500,16500)]:
    print('raw window',lo,hi)
    for x,y in arr:
        if lo<=x<=hi:
            print(f'{x:9.2f} /4={x/4:8.2f} /10={x/10:8.2f} y={y:9.2f}')
print('\n=== data near 2D candidates ===')
for lo,hi in [(10300,10800),(26200,26800)]:
    print('raw window',lo,hi)
    for x,y in arr:
        if lo<=x<=hi:
            print(f'{x:9.2f} /4={x/4:8.2f} /10={x/10:8.2f} y={y:9.2f}')
